-- ===========================================================================
-- 008: assessment library. Applied to the live project 11 Oct 2026. Additive.
-- taxa: targets by EPPO code (weeds, pathogens, crops), each checked against
--   the EPPO Global Database on 11 Oct 2026.
-- measures: one row per measure key the apps score, with rating type, unit,
--   target, part rated, sample, direction and the canonical key where an
--   older key means the same thing. Existing score keys are all here, so
--   nothing scored is lost and labels now come from this table.
-- assessment_sets: standard assessment schedules by trial type.
-- ===========================================================================
create table if not exists public.taxa (
  code       text primary key,
  scientific text not null,
  common     text,
  kind       text not null check (kind in ('weed', 'pathogen', 'insect', 'crop', 'other')),
  note       text,
  source     text
);

create table if not exists public.measures (
  key           text primary key,
  label         text not null,
  rating        text not null,
  unit          text,
  target        text references public.taxa (code),
  part          text,
  sample        text,
  higher_better boolean not null default false,
  min           numeric,
  max           numeric,
  decimals      integer not null default 1,
  group_key     text,
  canonical     text references public.measures (key),
  note          text,
  active        boolean not null default true
);

create table if not exists public.assessment_sets (
  key        text primary key,
  org_id     uuid references public.orgs,
  trial_type text not null,
  name       text not null,
  items      jsonb not null default '[]',
  note       text
);

alter table public.taxa enable row level security;

create policy taxa_read on public.taxa for select using (true);

create policy taxa_write on public.taxa for all using (auth.uid() is not null) with check (auth.uid() is not null);

alter table public.measures enable row level security;

create policy measures_read on public.measures for select using (true);

create policy measures_write on public.measures for all using (auth.uid() is not null) with check (auth.uid() is not null);

alter table public.assessment_sets enable row level security;

create policy assessment_sets_read on public.assessment_sets for select using (org_id is null or org_id = current_org());

create policy assessment_sets_write on public.assessment_sets for all using (org_id = current_org()) with check (org_id = current_org());

