asure": "blackleg_uci_pct", "timing": "mid to late flowering"}, {"measure": "sclerotinia_pct", "timing": "late pod fill"}, {"measure": "blackleg_crown_pct", "timing": "windrowing"}, {"measure": "pod_count", "timing": "late pod fill"}, {"measure": "yield_t_ha", "timing": "harvest"}]'::jsonb),('forage','forage','Forage and pasture','[{"measure": "plants_m2", "timing": "establishment"}, {"measure": "vigour_1_5", "timing": "establishment"}, {"measure": "dm_probe_kg_ha", "timing": "each grazing", "note": "probe calibrated to cuts"}, {"measure": "dm_ungrazed_kg_ha", "timing": "each cut"}, {"measure": "dm_grazed_kg_ha", "timing": "each cut"}, {"measure": "feed_me", "timing": "each cut"}, {"measure": "feed_cp", "timing": "each cut"}]'::jsonb),('seed_nutrition','seed_nutrition','Seed treatment and nutrition','[{"measure": "emergence_pct", "timing": "14 to 21 DAS"}, {"measure": "plants_m2", "timing": "21 to 28 DAS"}, {"measure": "vigour", "timing": "GS30"}, {"measure": "ndvi", "timing": "GS30"}, {"measure": "ndvi", "timing": "GS39"}, {"measure": "dm_kg_ha", "timing": "GS39"}, {"measure": "yield_t_ha", "timing": "harvest"}, {"measure": "protein_pct", "timing": "harvest"}]'::jsonb),('variety','variety','Variety','[{"measure": "plants_m2", "timing": "establishment"}, {"measure": "gs", "timing": "fortnightly from GS30"}, {"measure": "incidence_pct", "timing": "GS39", "note": "per disease present"}, {"measure": "lodging_pct", "timing": "pre harvest"}, {"measure": "yield_t_ha", "timing": "harvest"}, {"measure": "protein_pct", "timing": "harvest"}, {"measure": "screenings_pct", "timing": "harvest"}, {"measure": "test_weight", "timing": "harvest"}]'::jsonb) on conflict (key) do nothing;
